// Regenerates the API types from the backend's committed contract (backend/openapi.json).
// Run after Aashita changes the API: `npm run gen:api`, then commit both generated files.
//
// openapi-typescript 7 declares a TypeScript 5 peer, which conflicts with this project's TS 6,
// so it runs through npx (its own install) instead of being a devDependency.
import { execFileSync } from 'node:child_process'
import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

const spec = fileURLToPath(new URL('../../backend/openapi.json', import.meta.url))
const typesOut = fileURLToPath(new URL('../src/api/schema.gen.ts', import.meta.url))
const endpointsOut = fileURLToPath(new URL('../src/api/endpoints.gen.ts', import.meta.url))

execFileSync('npx', ['--yes', 'openapi-typescript@7.13.0', spec, '--output', typesOut], { stdio: 'inherit' })

const doc = JSON.parse(readFileSync(spec, 'utf8'))
const endpoints = Object.entries(doc.paths)
  .flatMap(([path, ops]) => Object.keys(ops).map((method) => `${method.toUpperCase()} ${path}`))
  .sort()

writeFileSync(
  endpointsOut,
  `// Generated by scripts/gen-api.mjs from backend/openapi.json. Do not edit.
// Lets the UI enable a feature only once the backend actually serves its endpoint.
export const API_VERSION = ${JSON.stringify(doc.info.version)}

export const ENDPOINTS: readonly string[] = ${JSON.stringify(endpoints, null, 2)}
`,
)
console.log(`wrote ${endpoints.length} endpoints (API ${doc.info.version})`)
